import { people, totals, reviewed } from './event-model.mjs';
export const escapeHtml = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const e=escapeHtml;
const money=value=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(value);
const logo=file=>`<img src="assets/${file}" alt="">`;
export const scenes=[
 {title:'A small change. A real commitment.',lead:'Harbor Event Rentals · Northstar’s Friday event · Fictional example'},
 {title:'Three people use AI. All three do their part.',lead:'Each person reviews the AI output and saves the work in their own system.'},
 {title:'The customer is still waiting for one answer.',lead:'The answers exist. Leah still has to turn them into a confirmed order.'},
 {title:'Now the work moves with the request.',lead:'Same people. Same decisions. The workflow carries the approved facts between systems.'},
 {title:'One change. One complete answer.',lead:'The order, delivery plan and customer record now agree.'}
];
function email(state,final=false){const n=totals(state);return `<section class="mail-window"><div class="appbar">${logo('ms-outlook.svg')}<b>Outlook</b><span>${final?'Leah’s draft · Not sent':'Inbox · Leah / Customer Service'}</span></div><div class="mail-meta"><small>${final?'TO RACHEL MORGAN · NORTHSTAR':'ORIGINAL REQUEST · RACHEL MORGAN / NORTHSTAR'}</small><h2>${final?'Your Friday event is updated':'RE: Friday’s event rental order'}</h2><span>${final?'Subject to Leah’s final send review':'Today, 10:12 AM · To Leah Chen'}</span></div><div class="mail-body">${final?`<p>Hi Rachel,</p><p>Your revised order is confirmed for <mark>${state.request.chairs} chairs and ${state.request.tables} tables</mark>, delivered Friday by <mark>9:00 AM</mark> to the same venue.</p><p>The additional equipment and delivery add <b>${money(n.extra)}</b>, as approved. Your revised total is <b>${money(n.total)} before tax</b>.</p><p>The equipment and second truck are reserved on the same updated order.</p><p>Thanks,<br>Leah</p>`:`<p>Hi Leah,</p><p>We’ve had more people RSVP. Can we increase Friday’s event from <mark>120 to 160 guests</mark>?</p><p>Please add <b>40 chairs and 10 tables</b>. Same venue, same <b>9:00 AM delivery</b>. Let me know the extra cost before you confirm.</p><p>Thanks for handling this,<br>Rachel</p>`}</div>${final?'':`<div class="mail-attachment"><span>Original order · HR-1042</span><b>120 chairs · 30 tables · ${money(n.base)} before tax</b></div>`}</section>`;}
const chats=[
 {prompt:'Log Rachel’s change and draft an acknowledgment. Keep the delivery time. Don’t confirm the final price yet.',answer:'Request recorded: 160 guests, 40 more chairs and 10 more tables. Friday, 9:00 AM remains requested.',human:'I’ve saved the request in HubSpot. Give me a reply I can send.',result:'“I’ll check the equipment and delivery, then send you the full added cost for approval.”',record:'HubSpot · Customer request',rows:[['Order','HR-1042'],['Guest count','160'],['Requested addition','40 chairs + 10 tables'],['Status','Awaiting final confirmation']],note:'Leah saved the request. HubSpot does not yet contain the approved delivery change.'},
 {prompt:'Use the rental inventory and this request to prepare the extra equipment for HR-1042.',answer:'The inventory record shows 40 chairs and 10 tables available. I’ve prepared the additional pick list for your review.',human:'I checked the stock and saved a temporary hold. Draft the reply to Leah.',result:'“The extra 40 chairs and 10 tables are held. Update the final rental order once the change is approved.”',record:'Rental inventory · Temporary hold',rows:[['Added equipment cost','+$400 at existing rates'],['Additional chairs','40 held'],['Additional tables','10 held'],['Status','Local inventory review complete']],note:'Copilot has inventory context here. Sam’s saved hold does not update dispatch or the customer’s total.'},
 {prompt:'Use the dispatch board and the added equipment to prepare a delivery plan for Friday by 9 AM.',answer:'The revised load needs a second truck in this sample plan. A truck and driver are available; the added delivery charge is $180.',human:'I checked the driver and route. Save the plan pending customer approval and draft my reply.',result:'“Second truck planned for the same 9 AM slot. Add $180 delivery. Release the plan after the customer approves.”',record:'Dispatch board · Revised plan',rows:[['Order','HR-1042'],['Delivery','Friday · 9:00 AM'],['Trucks','2 planned'],['Added delivery','+$180 · pending approval']],note:'Claude has dispatch context here. Dana’s saved plan does not update the rental order or customer total.'}
];
function localWork(state){const index=state.person;const person=people[index];const chat=chats[index];return `<div class="person-tabs" role="tablist" aria-label="Employee workspace">${people.map((p,i)=>`<button role="tab" aria-selected="${i===index}" data-person="${i}"><b>${p.name}</b><span>${p.department}</span></button>`).join('')}</div><div class="workbench"><section class="conversation"><div class="chat-header">${logo(person.icon)}<b>${person.ai}</b><span>${person.name}’s workspace · Initial request</span></div><div class="chat-turn user"><small>${person.name}</small><p>${chat.prompt}</p></div><div class="chat-turn assistant"><small>${person.ai}</small><p>${chat.answer}</p></div><div class="chat-turn user"><small>${person.name}</small><p>${chat.human}</p></div><div class="chat-result"><small>THE USEFUL OUTPUT</small><p><mark>${chat.result}</mark></p></div></section><aside class="local-record"><div class="record-header"><small>SAVED IN THEIR OWN SYSTEM</small><h2>${chat.record}</h2></div><dl>${chat.rows.map(([label,value])=>`<div><dt>${label}</dt><dd>${value}</dd></div>`).join('')}</dl><p class="record-note">${chat.note}</p></aside></div>`;}
function manual(){return `<div class="manual-desk"><aside class="inbox-list"><small>INITIAL REQUEST · LEAH HAS THE ANSWERS</small><button data-detail="sam"><b>Sam · Warehouse</b><span>Extra furniture held. +$400.</span><small>Rental inventory ↗</small></button><button data-detail="dana"><b>Dana · Dispatch</b><span>Second truck planned. +$180.</span><small>Dispatch board ↗</small></button><div class="message-preview"><b>Both did their jobs.</b><p>Their AI helped them finish. Leah now has to open the records, combine the price and get the customer’s approval.</p></div></aside><section class="draft-block"><div class="appbar">${logo('ms-outlook.svg')}<b>Leah → Rachel</b><span>Draft · Still working</span></div><div class="mail-meta"><small>CUSTOMER CONFIRMATION</small><h2>Your Friday order</h2></div><div class="mail-body"><p>Hi Rachel,</p><p>We can add the 40 chairs and 10 tables for <b>$400</b>. A second truck adds <b>$180</b>, bringing the change to <b>$580 before tax</b>.</p><p>Please approve the extra cost. I’ll then finalize the rental order and delivery plan.</p><p>Thanks,<br>Leah</p><p class="draft-hold">AI drafted the reply. Leah still has to collect approval, release the changes and verify three records.</p></div></section></div>`;}
function activity(state){const entries=[
 ['Request linked','Rachel’s email → HR-1042'],
 [reviewed(state,'sam')?'Sam approved inventory':'Sam’s inventory review',`${state.request.chairs-120} chairs + ${state.request.tables-30} tables → revised order`],
 [reviewed(state,'dana')?'Dana approved dispatch':'Dana’s dispatch review','Second truck → +$180 delivery'],
 [reviewed(state,'rachel')?'Rachel approved the extra cost':'Rachel’s price approval',`${money(totals(state).extra)} added → ${money(totals(state).total)} total`]
 ];return `<aside class="activity-panel"><small>DECISIONS STAY WITH PEOPLE</small>${entries.map(([title,text],i)=>`<div class="activity-entry ${i<=state.phase?'complete':''}"><b>${i===0||i<=state.phase?'✓ ':''}${title}</b><p>${text}</p></div>`).join('')}<button class="text-button" data-detail="build">What Nine-67 builds ↗</button></aside>`;}
function connected(state){const n=totals(state);const phase=state.phase;const messages=[
 ['The saved work is linked to one order.','Sam reviews the inventory hold. His approved quantities become the order update.'],
 [`Sam: “I approve ${state.request.chairs-120} extra chairs and ${state.request.tables-30} tables.”`,`Dana’s review now includes the approved ${state.request.chairs}-chair, ${state.request.tables}-table load. Leah did not copy it.`],
 ['Dana: “Second truck approved. Add $180 delivery.”',`Rachel receives one change: ${money(n.items)} equipment + ${money(n.transport)} delivery = ${money(n.extra)}. Her approval is still required.`],
 [`Rachel: “Approved. Please proceed with the extra ${money(n.extra)}.”`,'Leah can now authorize the order, dispatch and CRM updates. The workflow verifies all three.'],
 ['Every record agrees.','The confirmed order is ready for Leah’s final send review.']
 ];return `<div class="connected-record"><section class="order-sheet"><div class="order-title"><div><small>NINE-67 · ${state.ready?'VERIFIED ORDER':'PROPOSED ORDER · NOT RELEASED'}</small><h2>HR-1042 <span>Northstar · Friday, 9 AM</span></h2></div><span class="revision">Revision ${state.revision}</span></div><div class="change-summary"><b>120 → ${state.request.guests} guests</b><span>Same venue. Same delivery time.</span></div><table class="line-items"><thead><tr><th>Order item</th><th>Original</th><th>Revised</th><th>Added cost</th></tr></thead><tbody><tr><td>Chairs</td><td>120</td><td class="changed">${state.request.chairs}</td><td>${money((state.request.chairs-120)*5)}</td></tr><tr><td>Tables</td><td>30</td><td class="changed">${state.request.tables}</td><td>${money((state.request.tables-30)*20)}</td></tr><tr><td>Delivery</td><td>1 truck</td><td class="changed">2 trucks</td><td>${money(n.transport)}</td></tr></tbody></table><div class="total-row"><span>${money(n.base)} original + ${money(n.extra)} change</span><b>${money(n.total)} <small>before tax</small></b></div><div class="approval-strip"><b>${messages[phase][0]}</b><p>${messages[phase][1]}</p></div>${state.notice?`<p class="notice" role="status">${e(state.notice)}</p>`:''}</section>${activity(state)}</div>`;}
export function renderScene(state){if(state.scene===0)return email(state);if(state.scene===1)return localWork(state);if(state.scene===2)return manual();if(state.scene===3)return connected(state);if(!state.ready)return `<section class="empty-state"><h2>The change still needs approval.</h2><p>Complete the owner reviews and verified updates before preparing the confirmation.</p><button data-action="review-scene">Return to the workflow →</button></section>`;return `${email(state,true)}<div class="verified-receipt"><b>Simulated updates verified</b><span>Rental order ✓</span><span>Dispatch plan ✓</span><span>HubSpot ✓</span></div>`;}
export function primaryAction(state){if(state.scene===0)return {label:'See how the team uses AI →',action:'next'};if(state.scene===1)return state.person<2?{label:`See ${people[state.person+1].name}’s workspace →`,action:'next-person'}:{label:'See what’s still manual →',action:'next'};if(state.scene===2)return {label:'Replay with connected work →',action:'next'};if(state.scene===3)return state.phase<3?{label:['Show Sam’s decision →','Show Dana’s decision →','Show Rachel’s approval →'][state.phase],action:'review'}:{label:state.ready?'See the customer answer →':state.notice?'Retry the approved updates →':'Release and verify the updates →',action:state.ready?'next':'release'};return state.ready?{label:'Find your manual handoffs →',action:'assessment'}:{label:'Complete the workflow →',action:'review-scene'};}
export function renderDetail(state,key){if(key==='sam'||key==='dana'){const index=key==='sam'?1:2;const chat=chats[index];return {title:`${people[index].name} · ${chat.record}`,html:`<p class="detail-quote">${chat.result}</p><p>${chat.note}</p>`};}if(key==='build')return {title:'What Nine-67 would build',html:`<div class="build-steps"><section><b>1. Connect the business records</b><p>Read the authorized customer request, inventory hold and dispatch plan. Keep their source IDs and versions together.</p></section><section><b>2. Carry the approved facts</b><p>Inventory quantities feed the order. Dispatch adds the delivery cost. The complete change goes to the customer for approval.</p></section><section><b>3. Finish and verify the work</b><p>After Leah authorizes release, update the rental order, dispatch plan and CRM. Verify every write, retry failures safely and hold confirmation if a source changes.</p></section></div><p class="detail-note">This demo uses simulated records and recorded human responses. Production connectors, permissions and customer-approval capture would be implemented for your systems. Private AI chat histories are not read.</p><button data-detail="exceptions">Inspect an exception →</button>`};if(key==='exceptions')return {title:'What if an update fails?',html:`<p>The confirmation stays blocked until all records agree with the approved request.</p><label>Simulated exception<select id="fault" ${state.ready?'disabled':''}>${[['none','No exception'],['dispatch','Dispatch update fails'],['revision','Customer changes the request before release']].map(([value,label])=>`<option value="${value}" ${state.fault===value?'selected':''}>${label}</option>`).join('')}</select></label><p>${e(state.notice||'Choose an exception, then continue the owner approvals and release.')}</p>`};if(key==='assessment')return {title:'Where is someone still carrying the work?',html:'<p class="detail-quote">Bring one workflow to your complimentary assessment.</p><p>Josh and Suuchi will map the systems, handoffs and decisions, then identify one practical place to connect the work.</p><div id="booking-content"><b>Type “assessment” and your workflow in the webinar chat.</b></div><p class="detail-note">Scheduled separately after the webinar.</p>'};return {title:'About this demonstration',html:'<p>Harbor Event Rentals, its customer, employees, quantities and prices are fictional. All AI chats, saved records, approvals and integrations are simulated. No customer message is sent, no inventory is reserved and no payment is processed. Prices are illustrative and before tax.</p><p>The local demo runs approval gates, source-revision checks and safe retries. The business systems represent this fictional company’s disconnected setup, not a claim about any vendor’s capabilities.</p>'};}
